A bounded-waiting mutual-exclusion algorithm uses `test_and_set()`. The exit section was changed so that `lock = false` happens **before** `waiting[j] = false`:

```c
// Initialization: boolean lock = false; boolean waiting[n] = {false};
// Process Pi:
do {
    waiting[i] = true;
    key = true;
    while (waiting[i] && key)
        key = test_and_set(&lock);
    waiting[i] = false;

    /* critical section */

    j = (i + 1) % n;
    while ((j != i) && !waiting[j])
        j = (j + 1) % n;

    if (j == i)
        lock = false;
    else {
        lock = false;
        waiting[j] = false;
    }
    /* remainder section */
} while (true);
```

