Writers can starve in the standard readers-writers problem if readers keep arriving. An extra semaphore `w` (initialized to 1) is added for FCFS order. Complete `writer()` and `reader()`.

```c
int read_count = 0;
semaphore mutex = 1;
semaphore rw_mutex = 1;
semaphore w = 1;

void writer() {
    while (1) {
        wait(w);
        wait(rw_mutex);
        signal(w);

        /* writing is performed */

        signal(rw_mutex);
    }
}

void reader() {
    while (1) {
        wait(w);
        wait(mutex);
        read_count++;
        if (read_count == 1)
            wait(rw_mutex);
        signal(mutex);
        signal(w);

        /* reading is performed */

        wait(mutex);
        read_count--;
        if (read_count == 0)
            signal(rw_mutex);
        signal(mutex);
    }
}
```

